const noteSources = [
  { url: 'https://note.com/hashtag/生成AI/rss', label: 'note #生成AI' },
  { url: 'https://note.com/hashtag/ChatGPT/rss', label: 'note #ChatGPT' },
  { url: 'https://note.com/hashtag/Claude/rss', label: 'note #Claude' },
  { url: 'https://note.com/hashtag/プロンプト/rss', label: 'note #プロンプト' },
  { url: 'https://note.com/hashtag/AIツール/rss', label: 'note #AIツール' }
];
return noteSources.map(src => ({ json: src }));

const processedUrls = $getWorkflowStaticData('global').noteProcessedUrls || [];
const items = $input.all();
const newItems = [];
for (const item of items) {
  const url = item.json.link || item.json.url;
  if (!url) continue;
  const pubDate = item.json.pubDate || item.json.isoDate;
  if (pubDate && (Date.now() - new Date(pubDate).getTime()) > 60 * 60 * 1000) continue;
  if (!processedUrls.includes(url)) {
    newItems.push({ json: { title: item.json.title || 'タイトルなし', link: url, pubDate: item.json.pubDate || new Date().toISOString(), summary: item.json.contentSnippet || '', creator: item.json.creator || '不明' } });
  }
}
const allUrls = [...processedUrls, ...newItems.map(i => i.json.link)];
$getWorkflowStaticData('global').noteProcessedUrls = allUrls.slice(-300);
return newItems.length > 0 ? newItems : [{ json: { skip: true } }];

const GITHUB_TOKEN = $env.GITHUB_TOKEN || '';
const BASE = 'https://api.github.com/repos/liquitex-coder/ai-solution-/contents/n8n/prompts/';
const headers = { 'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'n8n-ai-navi/1.0' };
if (GITHUB_TOKEN) headers['Authorization'] = `token ${GITHUB_TOKEN}`;
const __httpRequest = this.helpers.httpRequest.bind(this.helpers);
async function fetchPrompt(file) {
  try {
    const data = await __httpRequest({ method: 'GET', url: BASE + file, headers, json: true });
    return Buffer.from((data.content || '').replace(/\n/g, ''), 'base64').toString('utf8');
  } catch(e) { return ''; }
}
const [copyright, wfPrompt] = await Promise.all([
  fetchPrompt('00-copyright-transform.md'),
  fetchPrompt('05-note-monitor.md')
]);
return [{ json: { ...$json, promptContent: copyright + '\n\n---\n\n' + wfPrompt } }];

